function() {
        const installedAppJsonStr = Hisense_FileRead('websdk/Appinfo.json', 6)
        if (isString(installedAppJsonStr)) {
            try {
                let presetAppObj = JSON.parse(installedAppJsonStr)
                return presetAppObj
            } catch (e) {
                return 0
            }
        } else {
            return 0
        }
    }
